<template>
<section aria-label="当前批次评测总览" class="insights">
  <h2>批次总览与版本比较</h2><p>以下仅统计当前已核验批次。候选使用同一完整样本范围、评分规则和重复策略；筛选同时作用于概览、比较及原始结果。没有固定结果时不推算结论。</p>
  <div class="filters"><el-select v-model="sampleId" clearable placeholder="全部样本" aria-label="筛选样本"><el-option v-for="item in request.samples" :key="item.sample_id" :label="item.document_type + ' · ' + item.sample_id" :value="item.sample_id"/></el-select><el-select v-model="split" clearable placeholder="全部来源分组" aria-label="筛选来源分组"><el-option label="开发" value="DEVELOPMENT"/><el-option label="调优" value="TUNING"/><el-option label="验收" value="ACCEPTANCE"/></el-select><el-select v-model="dimension" clearable placeholder="全部维度" aria-label="筛选维度"><el-option v-for="item in request.required_dimensions" :key="item" :label="item" :value="item"/></el-select><el-button @click="sampleId = ''; split = ''; dimension = ''">清除筛选</el-button></div>
  <p>范围：项目 {{ request.project_id ?? '企业级' }} · 规则 {{ request.rule_revision.version_id }} · 批次修订 {{ view.revision }}。{{ request.environment === 'SIMULATION' ? '仿真来源不能作为真实业务验收。' : '真实来源声明仍以服务端核验为准。' }}</p>
  <div class="metrics"><article><span>范围内样本</span><strong>{{ samples.length }}</strong><small>真实来源声明 {{ samples.filter(item => item.evidence_class === 'REAL').length }}；仿真 {{ samples.filter(item => item.evidence_class === 'SIMULATION').length }}</small></article><article><span>应有评分单元</span><strong>{{ expectedCount }}</strong><small>样本 × 全部候选 × 维度 × 重复</small></article><article><span>有效观察 / 应有单元</span><strong>{{ observedCount }} / {{ expectedCount }}</strong><small>观察记录数量不代表通过</small></article><article><span>固定结果</span><strong>{{ view.result ? evaluationVerdictLabels[view.result.verdict] : '尚未固定' }}</strong><small>整批结论，不随筛选变化</small></article></div>
  <el-table :data="comparison" row-key="version_id" border aria-label="同批次候选比较"><el-table-column prop="version_id" label="候选固定版本" min-width="220"/><el-table-column prop="expected" label="应有单元" width="100"/><el-table-column prop="observed" label="有效观察" width="100"/><el-table-column label="通过 / 未通过 / 证据不足" min-width="210"><template #default="scope">{{ view.result ? scope.row.pass + ' / ' + scope.row.fail + ' / ' + scope.row.insufficient : '尚无固定结果' }}</template></el-table-column><el-table-column label="解释" min-width="200"><template #default>计数来自当前批次，不代表质量改善或生产准入。</template></el-table-column></el-table>
  <p>人工采纳、退回率、调用成本及跨批次比较：当前接口未提供可核验数据。</p>
  <h3>筛选范围内原始结果</h3><el-table :data="resultPage" border empty-text="当前范围没有固定结果单元"><el-table-column prop="cell.sample_id" label="样本" min-width="200"/><el-table-column prop="cell.agent_version_id" label="候选版本" min-width="200"/><el-table-column prop="cell.dimension" label="维度" width="100"/><el-table-column prop="cell.repeat_index" label="重复索引" width="100"/><el-table-column label="结论与原因" min-width="250"><template #default="scope">{{ evaluationVerdictLabels[scope.row.status as EvaluationVerdict] }} · {{ evaluationRequirementLabel(scope.row.reason) }}</template></el-table-column><el-table-column prop="value" label="实际值" width="110"/></el-table><el-pagination v-if="cells.length > 20" v-model:current-page="resultNumber" :total="cells.length" :page-size="20" layout="prev, pager, next"/>
  <h3>评分审计记录</h3><p>此处为评测评分历史，包含原始观察和追加修订；不替代访问拒绝、调用或企业审计事件。共 {{ audit.length }} 条匹配记录。</p>
  <div class="filters"><el-select v-model="candidateId" clearable placeholder="全部候选（审计）" aria-label="筛选审计候选"><el-option v-for="item in request.candidates" :key="item.version_id" :label="item.version_id" :value="item.version_id"/></el-select><el-select v-model="actor" clearable placeholder="全部评分人员" aria-label="筛选评分人员"><el-option v-for="item in actors" :key="item" :label="item" :value="item"/></el-select><el-select v-model="historyState" clearable placeholder="全部修订状态" aria-label="筛选修订状态"><el-option label="当前有效" value="effective"/><el-option label="已被修订" value="superseded"/></el-select><label>起始日期（UTC）<el-input v-model="auditFrom" type="date" aria-label="审计起始日期（UTC）"/></label><label>结束日期（UTC）<el-input v-model="auditTo" type="date" aria-label="审计结束日期（UTC）"/></label></div>
  <p v-if="auditFrom && auditTo && auditFrom > auditTo" role="alert">起始日期不能晚于结束日期，请调整日期范围。</p>
  <el-table :data="auditPage" row-key="score_id" border empty-text="当前范围没有评分审计记录"><el-table-column label="样本 / 候选" min-width="250"><template #default="scope">{{ scope.row.observation.cell.sample_id }}<br/>{{ scope.row.observation.cell.agent_version_id }}</template></el-table-column><el-table-column label="维度 / 重复" width="140"><template #default="scope">{{ scope.row.observation.cell.dimension }} / {{ scope.row.observation.cell.repeat_index }}</template></el-table-column><el-table-column label="修订状态" width="130"><template #default="scope">{{ effectiveIds.has(scope.row.score_id) ? '当前有效' : '已被修订' }}</template></el-table-column><el-table-column label="评分人员 / 时间" min-width="220"><template #default="scope">{{ scope.row.scorer_id }}<br/>{{ scope.row.created_at }}</template></el-table-column><el-table-column prop="observation.reason" label="观察理由" min-width="180"/><el-table-column type="expand"><template #default="scope"><el-descriptions :column="1" border><el-descriptions-item label="评分标识">{{ scope.row.score_id }}</el-descriptions-item><el-descriptions-item label="修订前记录">{{ scope.row.observation.supersedes ?? '初始观察' }}</el-descriptions-item><el-descriptions-item label="观察状态">{{ scope.row.observation.status }}</el-descriptions-item><el-descriptions-item label="符合 / 适用项目数">{{ scope.row.observation.numerator ?? '未知' }} / {{ scope.row.observation.denominator ?? '未知' }}</el-descriptions-item><el-descriptions-item label="未知 / 违反项目数">{{ scope.row.observation.unknown_count ?? '未知' }} / {{ scope.row.observation.violation_count ?? '未知' }}</el-descriptions-item><el-descriptions-item label="固定输出">{{ scope.row.observation.output_ref?.version_id ?? '无输出引用' }}</el-descriptions-item><el-descriptions-item label="授权记录">{{ scope.row.authority_grant_id }} · 修订 {{ scope.row.authority_revision }}</el-descriptions-item></el-descriptions><el-collapse><el-collapse-item title="完整依据、摘要及原始审计字段"><pre>{{ JSON.stringify(scope.row, null, 2) }}</pre></el-collapse-item></el-collapse></template></el-table-column></el-table><el-pagination v-if="audit.length > 20" v-model:current-page="auditNumber" :total="audit.length" :page-size="20" layout="prev, pager, next"/>
</section>
</template>
<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { effectiveEvaluationScores, evaluationVerdictLabels, evaluationRequirementLabel } from '@/api/medical/evaluation-domain'
import type { EvaluationRead, EvaluationCell, EvaluationVerdict } from '@/api/medical/evaluation-domain'
const props = defineProps<{ view: EvaluationRead }>()
const sampleId = ref(''), split = ref(''), dimension = ref(''), candidateId = ref(''), actor = ref(''), historyState = ref(''), auditFrom = ref(''), auditTo = ref(''), resultNumber = ref(1), auditNumber = ref(1)
const request = computed(() => props.view.definition.request)
const samples = computed(() => request.value.samples.filter(item => (!sampleId.value || item.sample_id === sampleId.value) && (!split.value || item.split === split.value)))
const sampleIds = computed(() => new Set(samples.value.map(item => item.sample_id)))
function matches(cell: EvaluationCell) { return sampleIds.value.has(cell.sample_id) && (!dimension.value || dimension.value === cell.dimension) }
const effective = computed(() => [...effectiveEvaluationScores(props.view.definition, props.view.content_sha256, props.view.score_history).values()])
const effectiveIds = computed(() => new Set(effective.value.map(item => item.score_id)))
const cells = computed(() => props.view.result?.cells.filter(item => matches(item.cell)) ?? [])
const expectedPerCandidate = computed(() => samples.value.length * (dimension.value ? 1 : request.value.required_dimensions.length) * request.value.variance_policy.repeat_count)
const expectedCount = computed(() => expectedPerCandidate.value * request.value.candidates.length)
const observedCount = computed(() => effective.value.filter(item => matches(item.observation.cell)).length)
const comparison = computed(() => request.value.candidates.map(candidate => { const values = cells.value.filter(item => item.cell.agent_version_id === candidate.version_id); return { version_id: candidate.version_id, expected: expectedPerCandidate.value, observed: effective.value.filter(item => matches(item.observation.cell) && item.observation.cell.agent_version_id === candidate.version_id).length, pass: values.filter(item => item.status === 'PASS').length, fail: values.filter(item => item.status === 'FAIL').length, insufficient: values.filter(item => item.status === 'INSUFFICIENT_EVIDENCE').length } }))
const actors = computed(() => [...new Set(props.view.score_history.map(item => item.scorer_id))])
const audit = computed(() => props.view.score_history.filter(item => matches(item.observation.cell) && (!candidateId.value || item.observation.cell.agent_version_id === candidateId.value) && (!actor.value || item.scorer_id === actor.value) && (!auditFrom.value || item.created_at.slice(0, 10) >= auditFrom.value) && (!auditTo.value || item.created_at.slice(0, 10) <= auditTo.value) && (!historyState.value || effectiveIds.value.has(item.score_id) === (historyState.value === 'effective'))))
const resultPage = computed(() => cells.value.slice((resultNumber.value - 1) * 20, resultNumber.value * 20)), auditPage = computed(() => audit.value.slice((auditNumber.value - 1) * 20, auditNumber.value * 20))
watch([sampleId, split, dimension, candidateId, actor, historyState, auditFrom, auditTo, () => props.view], () => { resultNumber.value = 1; auditNumber.value = 1 })
</script>
<style scoped>.filters{display:flex;flex-wrap:wrap;gap:12px;margin:20px 0}.filters .el-select{width:230px}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin:24px 0}.metrics article{padding:18px;border:1px solid #DCE3EC;border-radius:8px;background:#F8FAFC}.metrics span,.metrics strong,.metrics small{display:block;overflow-wrap:anywhere}.metrics strong{font-size:23px;margin:12px 0}.metrics small,p{color:#526279;line-height:1.6}.el-pagination{margin:20px 0}pre{white-space:pre-wrap;overflow-wrap:anywhere}h3{margin-top:28px}@media(max-width:900px){.metrics{grid-template-columns:1fr 1fr}}@media(max-width:550px){.metrics{grid-template-columns:1fr}}</style>
